"""Core tests with fake callbacks and real media generated by ffmpeg.

Usage: python3 tests/test_core.py <media_dir> [en|it]
(generate the media dir with tests/make_media.py). A whole run uses one language:
commands are typed with that language's words; the other language's aliases are checked too.
"""

import io
import os
import shutil
import sys
import tempfile

from PIL import Image

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "bridge"))
from core import FIELD_AUDIO, FIELD_FILE_ATTACHMENTS, FIELD_IMAGE, Core, Limits  # noqa: E402
from i18n import make_t  # noqa: E402
from media import AM_CODEC2_2400, AM_OPUS_OGG  # noqa: E402

MEDIA = sys.argv[1]
LANG = sys.argv[2] if len(sys.argv) > 2 else "en"
T = make_t(LANG)
OTHER = "it" if LANG == "en" else "en"
# the commands as a user of each language would type them
CMD = {"en": dict(pending="/pending", download="/download", cancel="/cancel", follow="/follow",
                  quality="/quality", low="low", medium="medium", original="original", high="high"),
       "it": dict(pending="/pendenti", download="/scarica", cancel="/annulla", follow="/segui",
                  quality="/qualita", low="basso", medium="medio", original="originale", high="alto")}
C, X = CMD[LANG], CMD[OTHER]

work = tempfile.mkdtemp()
spool = os.path.join(work, "spool")
os.makedirs(spool)

lx, wa = [], []
core = Core(os.path.join(work, "state.json"), spool, Limits(),
            lx_send=lambda t, f: lx.append((t, f)), wa_send=wa.append, log=lambda s: None, lang=LANG)


def spooled(name):
    dst = os.path.join(spool, "wa-" + name)
    shutil.copy(os.path.join(MEDIA, name), dst)
    return dst


def ev(**kw):
    base = {"ev": "msg", "chat": "393331112222@s.whatsapp.net", "is_group": False,
            "chat_name": "Mario", "sender_name": "Mario", "kind": "text", "text": ""}
    base.update(kw)
    return base


ok = 0


def check(cond, what):
    global ok
    if not cond:
        print("FAILED:", what)
        print("  lx:", [(t, list(f)) for t, f in lx[-3:]])
        print("  wa:", wa[-3:])
        sys.exit(1)
    ok += 1
    print("ok  ", what)


print(f"== language: {LANG}")

# --- text DM
core.on_wa_event(ev(text="hello"))
check(lx[-1] == ("#1 Mario: hello", {}), "text DM with #1 header")

# --- image: low preset, under the threshold, delivered at once
core.on_wa_event(ev(kind="image", path=spooled("foto.jpg"), text="look", size=75362))
t, f = lx[-1]
img = f.get(FIELD_IMAGE)
check(img and img[0] == "webp" and len(img[1]) < 32 * 1024 and t == "#1 Mario: look",
      f"photo 1920x1080 75 KB -> webp low {len(img[1]) if img else '?'} B")
w, h = Image.open(io.BytesIO(img[1])).size
check(max(w, h) == 320, f"longest side 320 px ({w}x{h})")
check(not os.path.exists(os.path.join(spool, "wa-foto.jpg")), "spool cleaned")

# --- short voice note: codec2 2400 inline
core.on_wa_event(ev(kind="audio", path=spooled("vo10.ogg"), ptt=True))
a = lx[-1][1].get(FIELD_AUDIO)
check(a and a[0] == AM_CODEC2_2400 and 2900 <= len(a[1]) <= 3100, f"voice 10 s -> codec2 2400 {len(a[1]) if a else '?'} B")

# --- long voice note: over the threshold -> confirmation
core.on_wa_event(ev(kind="audio", path=spooled("vo130.ogg"), ptt=True))
t, f = lx[-1]
label = T("label_voice", secs="130", level=T("level_low"))
check(f == {} and f"{C['download']} 1" in t and label in t, f"voice 130 s pending: {t!r}")

# --- video: over the threshold -> confirmation
core.on_wa_event(ev(kind="video", path=spooled("vid.mp4"), mime="video/mp4", text="clip"))
t, f = lx[-1]
check(f == {} and f"{C['download']} 2" in t and "LoRa" in t, f"video pending: {t!r}")

# --- small document: inline
core.on_wa_event(ev(kind="document", path=spooled("small.bin"), filename="note.bin", mime="application/octet-stream"))
fa = lx[-1][1].get(FIELD_FILE_ATTACHMENTS)
check(fa and fa[0][0] == "note.bin" and len(fa[0][1]) == 5000, "5 KB file inline")

# --- pending list, download, cancel
core.on_lxmf(C["pending"], {})
check("1:" in lx[-1][0] and "2:" in lx[-1][0], "pending list shows 2 media")
core.on_lxmf(f"{C['download']} 1", {})
a = lx[-1][1].get(FIELD_AUDIO)
check(a and a[0] == AM_CODEC2_2400 and len(a[1]) > 32 * 1024, f"download 1 delivers the long voice note {len(a[1])} B")
core.on_lxmf(f"{C['cancel']} 2", {})
check(lx[-1][0] == T("cancel_ok", n=2) and not core.st["pending"], "cancel 2")
check(not any(n.startswith("pending-") for n in os.listdir(spool)), "pending blobs removed")
core.on_lxmf(X["pending"], {})
check(lx[-1][0] == T("pending_none"), f"other language alias works ({X['pending']})")

# --- groups: not followed -> dropped, then follow
n_before = len(lx)
core.on_wa_event(ev(chat="12036300@g.us", is_group=True, chat_name="Family", sender_name="Aunt", text="lunch?"))
check(len(lx) == n_before, "unfollowed group not forwarded")
core.on_lxmf("/chat", {})
check("#2 Family" + T("tag_group") in lx[-1][0], "group shows up in /chat")
core.on_lxmf(f"{C['follow']} 2", {})
check(lx[-1][0] == T("follow_ok", n=2, name="Family"), "follow confirmed")
core.on_wa_event(ev(chat="12036300@g.us", is_group=True, chat_name="Family", sender_name="Aunt", text="lunch?"))
check(lx[-1][0] == "#2 Family/Aunt: lunch?", "followed group forwarded")

# --- outgoing: no active chat
core.on_lxmf("hi", {})
check(lx[-1][0] == T("no_active_chat"), "text without active chat refused")
core.on_lxmf("/to 1", {})
core.on_lxmf("hi Mario", {})
check(wa[-1]["kind"] == "text" and wa[-1]["to"].startswith("39333") and wa[-1]["text"] == "hi Mario", "text to active chat")
core.on_lxmf("#2 coming", {})
check(wa[-1]["to"] == "12036300@g.us" and wa[-1]["text"] == "coming", "#N text")
core.on_lxmf("/r ok thanks", {})
check(wa[-1]["to"] == "12036300@g.us" and wa[-1]["text"] == "ok thanks", "/r to the last chat")
core.on_lxmf("/to +39 333 999 8888", {})
core.on_lxmf("test", {})
check(wa[-1]["to"] == "393339998888@s.whatsapp.net", "/to phone number")

# --- outgoing media: webp (as Sideband sends) -> jpeg
buf = io.BytesIO()
Image.new("RGB", (320, 240), (200, 30, 30)).save(buf, "webp", quality=22)
core.on_lxmf("photo", {FIELD_IMAGE: ["webp", buf.getvalue()]})
c = wa[-1]
check(c["kind"] == "image" and open(c["path"], "rb").read(2) == b"\xff\xd8" and c["text"] == "photo", "webp -> jpeg with caption")

# --- outgoing audio: codec2 and opus
core.on_lxmf("", {FIELD_AUDIO: [AM_CODEC2_2400, a[1]]})
c = wa[-1]
check(c["kind"] == "audio" and open(c["path"], "rb").read(4) == b"OggS", "codec2 -> ogg opus")
core.on_lxmf("", {FIELD_AUDIO: [AM_OPUS_OGG, open(os.path.join(MEDIA, "vo10.ogg"), "rb").read()]})
check(wa[-1]["kind"] == "audio" and open(wa[-1]["path"], "rb").read(4) == b"OggS", "Sideband opus ogg -> ogg")

# --- outgoing file
core.on_lxmf("", {FIELD_FILE_ATTACHMENTS: [["report.pdf", b"%PDF-1.4 test"]]})
check(wa[-1]["kind"] == "document" and wa[-1]["filename"] == "report.pdf" and wa[-1]["mime"] == "application/pdf",
      "attachment -> document")

# --- failed send reported by the sidecar
core.on_wa_event({"ev": "result", "req": wa[-1]["req"], "ok": False, "error": "WhatsApp down"})
check("WhatsApp down" in lx[-1][0] and "report.pdf" in lx[-1][0], "send failure notified")

# --- quality
core.on_lxmf(C["quality"], {})
check(f"{T('level_low')} ({T('img_desc_low')})" in lx[-1][0] and "Sideband" in lx[-1][0],
      "quality shows low/low by default")
core.on_lxmf(f"{C['quality']} img {C['medium']}", {})
check(lx[-1][0] == T("quality_set", what=T("quality_what_img"), level=T("level_medium"), desc=T("img_desc_medium")),
      "quality img medium")
core.on_wa_event(ev(kind="image", path=spooled("foto.jpg")))
img = lx[-1][1].get(FIELD_IMAGE)
w, h = Image.open(io.BytesIO(img[1])).size
check(img[0] == "webp" and max(w, h) == 640 and len(img[1]) > 1510, f"medium image 640 px, {len(img[1])} B")
core.on_lxmf(f"{X['quality']} img {X['original']}", {})   # the other language's words work too
core.on_wa_event(ev(kind="image", path=spooled("foto.jpg"), mime="image/jpeg"))
t_, f_ = lx[-1]
check(f_ == {} and T("level_original") in t_ and f"{C['download']} " in t_, "original image over threshold: pending")
pid = max(int(k) for k in core.st["pending"])
core.on_lxmf(f"{C['download']} {pid}", {})
img = lx[-1][1].get(FIELD_IMAGE)
check(img and img[0] == "jpg" and img[1] == open(os.path.join(MEDIA, "foto.jpg"), "rb").read(),
      "original delivered unchanged (jpg)")
core.on_lxmf(f"{C['quality']} audio {C['medium']}", {})
core.on_wa_event(ev(kind="audio", path=spooled("vo10.ogg"), ptt=True, seconds=10))
a2 = lx[-1][1].get(FIELD_AUDIO)
check(a2 and a2[0] == AM_OPUS_OGG and a2[1][:4] == b"OggS" and len(a2[1]) > 3000, f"medium audio: Opus ogg {len(a2[1])} B")
core.on_lxmf(f"{C['quality']} audio {C['original']}", {})
core.on_wa_event(ev(kind="audio", path=spooled("vo10.ogg"), ptt=True, seconds=10))
a3 = lx[-1][1].get(FIELD_AUDIO)
check(a3 and a3[0] == AM_OPUS_OGG and a3[1] == open(os.path.join(MEDIA, "vo10.ogg"), "rb").read(),
      "original audio unchanged")
core.on_lxmf(f"{C['quality']} photo toomuch", {})
check(lx[-1][0] == T("quality_usage"), "invalid level refused")

# --- automatic step-down when over the cap
lx2 = []
small = Core(os.path.join(work, "state2.json"), spool, Limits(max_file_mb=0.003),
             lambda t, f: lx2.append((t, f)), lambda c: None, log=lambda s: None, lang=LANG)
small.on_lxmf(f"{C['quality']} img {C['high']}", {})
small.on_wa_event(ev(kind="image", path=spooled("foto.jpg")))
t_, f_ = lx2[-1]
check(T("reduced_note", level=T("level_low")) in t_ and f_.get(FIELD_IMAGE, [None])[0] == "webp"
      and len(f_[FIELD_IMAGE][1]) <= 3 * 1024, "high too big: steps down to low on its own")

# --- sending big videos and files
core.on_lxmf("/to 1", {})
core.on_lxmf("look", {FIELD_FILE_ATTACHMENTS: [["clip.mp4", b"x" * 12_000_000]]})
check(wa[-1]["kind"] == "video" and wa[-1]["mime"] == "video/mp4" and wa[-1]["text"] == "look"
      and os.path.getsize(wa[-1]["path"]) == 12_000_000, "12 MB video sent as a WhatsApp video")
core.on_lxmf("", {FIELD_FILE_ATTACHMENTS: [["film.mp4", b"x" * (17 * 1024 * 1024)]]})
check(wa[-1]["kind"] == "document", "video over 16 MB sent as a document")

# --- status and unknown command
core.wa_status = "open"
core.on_lxmf("/status", {})
check("open" in lx[-1][0] and T("policy_followed") in lx[-1][0], "/status")
core.on_lxmf("/stato", {})
check("open" in lx[-1][0], "/stato alias")
core.on_lxmf("/nonsense", {})
check(lx[-1][0] == T("unknown_command", cmd="/nonsense"), "unknown command")
core.on_lxmf("/help", {})
check(lx[-1][0] == T("help"), "/help")
core.on_lxmf("/aiuto", {})
check(lx[-1][0] == T("help"), "/aiuto alias")

# --- persistence
core2 = Core(os.path.join(work, "state.json"), spool, Limits(), lambda t, f: None, lambda c: None,
             log=lambda s: None, lang=LANG)
check(core2.st["active"] == core.st["active"] and 2 in core2.st["follow"]
      and core2.st["quality"] == {"img": "original", "audio": "original"}, "state persisted (qualities too)")

# --- state written by alpha0.2 (Italian level names) is understood
import json  # noqa: E402
old = os.path.join(work, "old.json")
with open(old, "w") as f:
    json.dump({"quality": {"img": "medio", "audio": "originale"}, "next_chat": 1}, f)
core3 = Core(old, spool, Limits(), lambda t, f: None, lambda c: None, log=lambda s: None, lang=LANG)
check(core3.st["quality"] == {"img": "medium", "audio": "original"}, "alpha0.2 state (Italian levels) migrated")

print(f"\n{ok} checks passed")
shutil.rmtree(work)
